def member_discount_rate(points, levels):
    """返回积分对应的会员折扣率。levels 为升序的 (门槛积分, 折扣率)。"""
    rate = 0.0
    for threshold, level_rate in levels:
        if points > threshold:
            rate = level_rate
    return rate

