from target import member_discount_rate


def test_points_exactly_at_threshold_use_that_level():
    assert member_discount_rate(1000, [(1000, 0.05), (5000, 0.1)]) == 0.05


def test_points_below_first_threshold_get_no_discount():
    assert member_discount_rate(500, [(1000, 0.05)]) == 0.0


def test_points_between_levels_use_lower_level():
    assert member_discount_rate(2000, [(1000, 0.05), (5000, 0.1)]) == 0.05
